import time

class TTLCache:
    """Simple TTL cache for expensive operations."""
    def __init__(self, ttl: int = 60):
        self.ttl = ttl
        self.cache = {}

    async def get_or_set(self, key: str, fetch_func):
        now = time.time()
        if key in self.cache and now - self.cache[key]['timestamp'] < self.ttl:
            return self.cache[key]['value']
        value = await fetch_func()
        self.cache[key] = {'value': value, 'timestamp': now}
        return value

from typing import Callable, Any

class DataPipeline:
    """Chainable async data processing pipeline."""
    def __init__(self):
        self.stages = []

    def add_stage(self, stage: Callable):
        self.stages.append(stage)
        return self

    async def execute(self, data: Any) -> Any:
        for stage in self.stages:
            data = await stage(data)
        return data

